let searchTarget = "";
if (typeof query === "string") {
  searchTarget = query;
} else if (typeof query === "object" && query !== null) {
  searchTarget = query.query || query.input || query.searchQuery || query.q || "";
} else if (typeof input === "string") {
  searchTarget = input;
} else if (typeof input === "object" && input !== null) {
  searchTarget = input.query || input.input || input.searchQuery || input.q || "";
}

if (!searchTarget) {
  searchTarget = "canyon lake texas water level 78133";
}

const q = encodeURIComponent(searchTarget);

try {
  const data = await this.helpers.httpRequest({
    method: "GET",
    url: `http://searxng:8080/search?q=${q}&format=json`,
    json: true
  });
  const results = (data && data.results ? data.results : []).slice(0, 5).map((r, i) => `${i+1}. [${r.title}](${r.url})\n${r.content}`).join("\n\n");
  return results || "No results found for query: " + searchTarget;
} catch (err) {
  return `Error querying SearXNG: ${err.message}`;
}

